orders_2024 = len(df[df['year']==2024])
yoy_revenue = (rev_2024 - rev_2023) / rev_2023 * 100
yoy_profit = (prof_2024 - prof_2023) / prof_2023 * 100

# ── Monthly / Quarterly Trends ──────────────────────────────────────
monthly = df.groupby('month_dt').agg(
    revenue=('revenue','sum'),
    profit=('profit','sum'),
    orders=('order_id','count'),
    quantity=('quantity','sum'),
