def fmt_money(v):
    if abs(v) >= 1e6: return f'${v/1e6:,.2f}M'
    if abs(v) >= 1e3: return f'${v/1e3:,.1f}K'
    return f'${v:,.2f}'

def fmt_pct(v): return f'{v:+.1f}%' if v != 0 else '0.0%'
def fmt_num(v): return f'{v:,.0f}'

def build_table(headers, rows, align=None):
    html = '<table><thead><tr>'
    for h in headers:
        html += f'<th>{h}</th>'
    html += '</tr></thead><tbody>'
    for row in rows:
        html += '<tr>'
        for i, cell in enumerate(row):
            a = align[i] if align and i < len(align) else 'left'
            html += f'<td style="text-align:{a}">{cell}</td>'
        html += '</tr>'
    html += '</tbody></table>'
    return html

