#!/usr/bin/env python3
"""Chocolate Retail Sales Performance Report Generator (2023-2024)"""

import pandas as pd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
import base64
import io
import json
import textwrap
from datetime import datetime

# ── Load & prepare data ─────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv', parse_dates=['order_date'])
df['year'] = df['order_date'].dt.year
df['month'] = df['order_date'].dt.to_period('M')
df['quarter'] = df['order_date'].dt.to_period('Q')
df['month_dt'] = df['order_date'].dt.to_period('M').dt.to_timestamp()
df['profit_margin'] = df['profit'] / df['revenue']
df['has_discount'] = df['discount'] > 0

# Discount bands
def discount_band(d):
    if d == 0: return 'No Discount'
    elif d <= 0.05: return '1-5%'
    elif d <= 0.10: return '6-10%'
    elif d <= 0.15: return '11-15%'
    elif d <= 0.20: return '16-20%'
    else: return '>20%'
df['discount_band'] = df['discount'].apply(discount_band)

# ── KPIs ─────────────────────────────────────────────────────────────
total_revenue = df['revenue'].sum()
total_profit = df['profit'].sum()
avg_profit_margin = (df['profit'].sum() / df['revenue'].sum()) * 100
avg_order_value = df['revenue'].mean()
total_orders = len(df)
total_quantity = df['quantity'].sum()
discount_util_rate = df['has_discount'].mean() * 100

# YoY
rev_2023 = df[df['year']==2023]['revenue'].sum()
rev_2024 = df[df['year']==2024]['revenue'].sum()
prof_2023 = df[df['year']==2023]['profit'].sum()
prof_2024 = df[df['year']==2024]['profit'].sum()
orders_2023 = len(df[df['year']==2023])
orders_2024 = len(df[df['year']==2024])
yoy_revenue = (rev_2024 - rev_2023) / rev_2023 * 100
yoy_profit = (prof_2024 - prof_2023) / prof_2023 * 100

# ── Monthly / Quarterly Trends ──────────────────────────────────────
monthly = df.groupby('month_dt').agg(
    revenue=('revenue','sum'),
    profit=('profit','sum'),
    orders=('order_id','count'),
    quantity=('quantity','sum'),
    avg_margin=('profit_margin','mean')
).reset_index()
monthly['avg_margin'] *= 100

quarterly = df.groupby('quarter').agg(
    revenue=('revenue','sum'),
    profit=('profit','sum'),
    orders=('order_id','count')
).reset_index()
quarterly['quarter_str'] = quarterly['quarter'].astype(str)

# Monthly by year for overlay
monthly['year'] = monthly['month_dt'].dt.year
monthly['mo'] = monthly['month_dt'].dt.month

# ── Product Performance ──────────────────────────────────────────────
prod = df.groupby('product_id').agg(
    revenue=('revenue','sum'),
    profit=('profit','sum'),
    orders=('order_id','count'),
    quantity=('quantity','sum'),
    avg_price=('unit_price','mean')
).reset_index()
prod['margin'] = prod['profit'] / prod['revenue'] * 100
top10_rev = prod.nlargest(10, 'revenue')
top10_prof = prod.nlargest(10, 'profit')
bottom5_margin = prod.nsmallest(5, 'margin')

# ── Store Performance ────────────────────────────────────────────────
store = df.groupby('store_id').agg(
    revenue=('revenue','sum'),
    profit=('profit','sum'),
    orders=('order_id','count'),
    quantity=('quantity','sum')
).reset_index()
store['margin'] = store['profit'] / store['revenue'] * 100
top10_stores = store.nlargest(10, 'revenue')
bottom5_stores = store.nsmallest(5, 'revenue')

# ── Discount Analysis ────────────────────────────────────────────────
disc_band_order = ['No Discount','1-5%','6-10%','11-15%','16-20%','>20%']
disc = df.groupby('discount_band').agg(
    revenue=('revenue','sum'),
    profit=('profit','sum'),
    orders=('order_id','count'),
    avg_quantity=('quantity','mean'),
    avg_revenue=('revenue','mean'),
    avg_margin=('profit_margin','mean')
).reindex(disc_band_order).reset_index()
disc['avg_margin_pct'] = disc['avg_margin'] * 100
disc['revenue_share'] = disc['revenue'] / disc['revenue'].sum() * 100

discounted = df[df['has_discount']]
non_discounted = df[~df['has_discount']]
disc_summary = {
    'disc_avg_margin': discounted['profit_margin'].mean()*100 if len(discounted)>0 else 0,
    'nodisc_avg_margin': non_discounted['profit_margin'].mean()*100 if len(non_discounted)>0 else 0,
    'disc_avg_qty': discounted['quantity'].mean() if len(discounted)>0 else 0,
    'nodisc_avg_qty': non_discounted['quantity'].mean() if len(non_discounted)>0 else 0,
    'disc_avg_rev': discounted['revenue'].mean() if len(discounted)>0 else 0,
    'nodisc_avg_rev': non_discounted['revenue'].mean() if len(non_discounted)>0 else 0,
}

# ── Customer Analysis ────────────────────────────────────────────────
cust = df.groupby('customer_id').agg(
    revenue=('revenue','sum'),
    profit=('profit','sum'),
    orders=('order_id','count'),
    quantity=('quantity','sum'),
    avg_discount=('discount','mean')
).reset_index()
cust['aov'] = cust['revenue'] / cust['orders']
top20_customers = cust.nlargest(20, 'revenue')

# Customer segments by order frequency
cust['segment'] = pd.cut(cust['orders'], bins=[0,1,3,10,9999], labels=['One-time','Occasional','Regular','VIP'])
seg = cust.groupby('segment', observed=True).agg(
    customers=('customer_id','count'),
    total_revenue=('revenue','sum'),
    avg_revenue=('revenue','mean'),
    avg_orders=('orders','mean')
).reset_index()

# ── Chart Generation ─────────────────────────────────────────────────
COLORS = {
    'primary': '#4F46E5',
    'secondary': '#7C3AED',
    'accent': '#EC4899',
    'success': '#10B981',
    'warning': '#F59E0B',
    'danger': '#EF4444',
    'dark': '#1E293B',
    'muted': '#94A3B8',
    'bg': '#F8FAFC',
    'palette': ['#4F46E5','#7C3AED','#EC4899','#10B981','#F59E0B','#EF4444','#06B6D4','#8B5CF6']
}

plt.rcParams.update({
    'font.family': 'sans-serif',
    'font.size': 11,
    'axes.spines.top': False,
    'axes.spines.right': False,
    'axes.grid': True,
    'grid.alpha': 0.3,
    'grid.linestyle': '--',
    'figure.facecolor': 'white',
    'axes.facecolor': 'white',
})

def fig_to_base64(fig, dpi=130):
    buf = io.BytesIO()
    fig.savefig(buf, format='png', dpi=dpi, bbox_inches='tight', facecolor='white')
    buf.seek(0)
    b64 = base64.b64encode(buf.read()).decode()
    plt.close(fig)
    return b64

charts = {}

# 1. Monthly Revenue & Profit Trend
fig, ax1 = plt.subplots(figsize=(14, 5))
ax1.bar(monthly['month_dt'], monthly['revenue'], width=25, color=COLORS['primary'], alpha=0.7, label='Revenue')
ax1.bar(monthly['month_dt'], monthly['profit'], width=25, color=COLORS['success'], alpha=0.7, label='Profit')
ax1.set_xlabel('')
ax1.set_ylabel('Amount ($)')
ax1.set_title('Monthly Revenue & Profit (2023–2024)', fontsize=14, fontweight='bold', pad=15)
ax1.legend(loc='upper left')
ax1.yaxis.set_major_formatter(mticker.FuncFormatter(lambda x,_: f'${x/1e6:.1f}M' if x>=1e6 else f'${x/1e3:.0f}K'))
fig.autofmt_xdate()
charts['monthly_rev_profit'] = fig_to_base64(fig)

# 2. YoY Monthly Revenue Overlay
fig, ax = plt.subplots(figsize=(14, 5))
for yr, color, ls in [(2023, COLORS['muted'], '--'), (2024, COLORS['primary'], '-')]:
    yd = monthly[monthly['year']==yr].sort_values('mo')
    ax.plot(yd['mo'], yd['revenue'], color=color, linewidth=2.5, linestyle=ls, marker='o', markersize=6, label=str(yr))
ax.set_xticks(range(1,13))
ax.set_xticklabels(['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'])
ax.set_ylabel('Revenue ($)')
ax.set_title('Year-over-Year Monthly Revenue Comparison', fontsize=14, fontweight='bold', pad=15)
ax.legend()
ax.yaxis.set_major_formatter(mticker.FuncFormatter(lambda x,_: f'${x/1e6:.1f}M' if x>=1e6 else f'${x/1e3:.0f}K'))
charts['yoy_overlay'] = fig_to_base64(fig)

# 3. Quarterly Revenue
fig, ax = plt.subplots(figsize=(12, 5))
colors_q = [COLORS['primary'] if '2023' in s else COLORS['secondary'] for s in quarterly['quarter_str']]
bars = ax.bar(quarterly['quarter_str'], quarterly['revenue'], color=colors_q, alpha=0.85)
ax.set_ylabel('Revenue ($)')
ax.set_title('Quarterly Revenue (2023–2024)', fontsize=14, fontweight='bold', pad=15)
ax.yaxis.set_major_formatter(mticker.FuncFormatter(lambda x,_: f'${x/1e6:.1f}M' if x>=1e6 else f'${x/1e3:.0f}K'))
for bar in bars:
    h = bar.get_height()
    ax.text(bar.get_x()+bar.get_width()/2., h, f'${h/1e6:.2f}M', ha='center', va='bottom', fontsize=9, fontweight='bold')
charts['quarterly_rev'] = fig_to_base64(fig)

# 4. Monthly Order Volume
fig, ax = plt.subplots(figsize=(14, 4.5))
ax.fill_between(monthly['month_dt'], monthly['orders'], alpha=0.3, color=COLORS['secondary'])
ax.plot(monthly['month_dt'], monthly['orders'], color=COLORS['secondary'], linewidth=2)
ax.set_ylabel('Number of Orders')
ax.set_title('Monthly Order Volume (2023–2024)', fontsize=14, fontweight='bold', pad=15)
fig.autofmt_xdate()
charts['monthly_orders'] = fig_to_base64(fig)

# 5. Top 10 Products by Revenue
fig, ax = plt.subplots(figsize=(10, 5))
ax.barh(top10_rev['product_id'], top10_rev['revenue'], color=COLORS['primary'], alpha=0.85)
ax.set_xlabel('Revenue ($)')
ax.set_title('Top 10 Products by Revenue', fontsize=14, fontweight='bold', pad=15)
ax.invert_yaxis()
ax.xaxis.set_major_formatter(mticker.FuncFormatter(lambda x,_: f'${x/1e3:.0f}K'))
charts['top10_products'] = fig_to_base64(fig)

# 6. Top 10 Stores by Revenue
fig, ax = plt.subplots(figsize=(10, 5))
ax.barh(top10_stores['store_id'], top10_stores['revenue'], color=COLORS['secondary'], alpha=0.85)
ax.set_xlabel('Revenue ($)')
ax.set_title('Top 10 Stores by Revenue', fontsize=14, fontweight='bold', pad=15)
ax.invert_yaxis()
ax.xaxis.set_major_formatter(mticker.FuncFormatter(lambda x,_: f'${x/1e3:.0f}K'))
charts['top10_stores'] = fig_to_base64(fig)

# 7. Discount Impact: Margin by Discount Band
fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(14, 5))
band_colors = [COLORS['success'], COLORS['primary'], COLORS['primary'], COLORS['warning'], COLORS['warning'], COLORS['danger']]
ax1.bar(disc['discount_band'], disc['avg_margin_pct'], color=band_colors, alpha=0.85)
ax1.set_ylabel('Avg Profit Margin (%)')
ax1.set_title('Profit Margin by Discount Level', fontsize=13, fontweight='bold', pad=10)
ax1.tick_params(axis='x', rotation=30)
for i, v in enumerate(disc['avg_margin_pct']):
    ax1.text(i, v+0.3, f'{v:.1f}%', ha='center', fontsize=9, fontweight='bold')

ax2.bar(disc['discount_band'], disc['avg_quantity'], color=band_colors, alpha=0.85)
ax2.set_ylabel('Avg Quantity per Order')
ax2.set_title('Order Size by Discount Level', fontsize=13, fontweight='bold', pad=10)
ax2.tick_params(axis='x', rotation=30)
for i, v in enumerate(disc['avg_quantity']):
    ax2.text(i, v+0.05, f'{v:.2f}', ha='center', fontsize=9, fontweight='bold')
fig.tight_layout(pad=3)
charts['discount_impact'] = fig_to_base64(fig)

# 8. Discount band revenue share (pie)
fig, ax = plt.subplots(figsize=(7, 7))
wedges, texts, autotexts = ax.pie(
    disc['revenue_share'], labels=disc['discount_band'],
    autopct='%1.1f%%', colors=COLORS['palette'][:len(disc)],
    pctdistance=0.85, startangle=90
)
for t in autotexts: t.set_fontsize(10); t.set_fontweight('bold')
ax.set_title('Revenue Share by Discount Band', fontsize=14, fontweight='bold', pad=15)
charts['discount_pie'] = fig_to_base64(fig)

# 9. Customer Segments
fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(13, 5))
seg_colors = [COLORS['muted'], COLORS['primary'], COLORS['secondary'], COLORS['accent']]
ax1.bar(seg['segment'].astype(str), seg['customers'], color=seg_colors, alpha=0.85)
ax1.set_ylabel('Number of Customers')
ax1.set_title('Customer Count by Segment', fontsize=13, fontweight='bold', pad=10)
for i, v in enumerate(seg['customers']):
    ax1.text(i, v, f'{v:,}', ha='center', va='bottom', fontsize=9, fontweight='bold')

ax2.bar(seg['segment'].astype(str), seg['avg_revenue'], color=seg_colors, alpha=0.85)
ax2.set_ylabel('Avg Revenue per Customer ($)')
ax2.set_title('Avg Revenue by Segment', fontsize=13, fontweight='bold', pad=10)
for i, v in enumerate(seg['avg_revenue']):
    ax2.text(i, v, f'${v:.0f}', ha='center', va='bottom', fontsize=9, fontweight='bold')
fig.tight_layout(pad=3)
charts['customer_segments'] = fig_to_base64(fig)

# 10. Monthly Profit Margin Trend
fig, ax = plt.subplots(figsize=(14, 4.5))
ax.plot(monthly['month_dt'], monthly['avg_margin'], color=COLORS['success'], linewidth=2.5, marker='o', markersize=5)
ax.axhline(y=avg_profit_margin, color=COLORS['danger'], linestyle='--', alpha=0.6, label=f'Overall Avg ({avg_profit_margin:.1f}%)')
ax.set_ylabel('Avg Profit Margin (%)')
ax.set_title('Monthly Average Profit Margin Trend', fontsize=14, fontweight='bold', pad=15)
ax.legend()
fig.autofmt_xdate()
charts['margin_trend'] = fig_to_base64(fig)


# ── Build HTML ───────────────────────────────────────────────────────

def fmt_money(v):
    if abs(v) >= 1e6: return f'${v/1e6:,.2f}M'
    if abs(v) >= 1e3: return f'${v/1e3:,.1f}K'
    return f'${v:,.2f}'

def fmt_pct(v): return f'{v:+.1f}%' if v != 0 else '0.0%'
def fmt_num(v): return f'{v:,.0f}'

def build_table(headers, rows, align=None):
    html = '<table><thead><tr>'
    for h in headers:
        html += f'<th>{h}</th>'
    html += '</tr></thead><tbody>'
    for row in rows:
        html += '<tr>'
        for i, cell in enumerate(row):
            a = align[i] if align and i < len(align) else 'left'
            html += f'<td style="text-align:{a}">{cell}</td>'
        html += '</tr>'
    html += '</tbody></table>'
    return html

# Top products table
top_prod_rows = []
for _, r in top10_rev.iterrows():
    top_prod_rows.append([r['product_id'], fmt_money(r['revenue']), fmt_money(r['profit']), f"{r['margin']:.1f}%", fmt_num(r['orders']), fmt_num(r['quantity'])])
top_prod_table = build_table(['Product','Revenue','Profit','Margin','Orders','Qty Sold'], top_prod_rows, ['left','right','right','right','right','right'])

# Top stores table
top_store_rows = []
for _, r in top10_stores.iterrows():
    top_store_rows.append([r['store_id'], fmt_money(r['revenue']), fmt_money(r['profit']), f"{r['margin']:.1f}%", fmt_num(r['orders'])])
top_store_table = build_table(['Store','Revenue','Profit','Margin','Orders'], top_store_rows, ['left','right','right','right','right'])

# Bottom stores table
bottom_store_rows = []
for _, r in bottom5_stores.iterrows():
    bottom_store_rows.append([r['store_id'], fmt_money(r['revenue']), fmt_money(r['profit']), f"{r['margin']:.1f}%", fmt_num(r['orders'])])
bottom_store_table = build_table(['Store','Revenue','Profit','Margin','Orders'], bottom_store_rows, ['left','right','right','right','right'])

# Discount bands table
disc_rows = []
for _, r in disc.iterrows():
    disc_rows.append([r['discount_band'], fmt_money(r['revenue']), f"{r['revenue_share']:.1f}%", f"{r['avg_margin_pct']:.1f}%", f"{r['avg_quantity']:.2f}", fmt_money(r['avg_revenue']), fmt_num(r['orders'])])
disc_table = build_table(['Discount Band','Revenue','Rev Share','Avg Margin','Avg Qty','Avg Order Value','Orders'], disc_rows, ['left','right','right','right','right','right','right'])

# Customer segment table
seg_rows = []
for _, r in seg.iterrows():
    seg_rows.append([str(r['segment']), fmt_num(r['customers']), fmt_money(r['total_revenue']), fmt_money(r['avg_revenue']), f"{r['avg_orders']:.1f}"])
seg_table = build_table(['Segment','Customers','Total Revenue','Avg Revenue','Avg Orders'], seg_rows, ['left','right','right','right','right'])

# Quarterly table
q_rows = []
for _, r in quarterly.iterrows():
    q_rows.append([r['quarter_str'], fmt_money(r['revenue']), fmt_money(r['profit']), fmt_num(r['orders'])])
q_table = build_table(['Quarter','Revenue','Profit','Orders'], q_rows, ['left','right','right','right'])

# Top customers
top_cust_rows = []
for _, r in top20_customers.head(10).iterrows():
    top_cust_rows.append([r['customer_id'], fmt_money(r['revenue']), fmt_money(r['profit']), fmt_num(r['orders']), f"${r['aov']:.2f}", f"{r['avg_discount']*100:.1f}%"])
